package net.civeira.phylax.feature.identity.userprofile.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.userprofile.domain.UserProfile;
import net.civeira.phylax.feature.identity.userprofile.domain.valueobject.BirthdateVO;

class BirthdateValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of birthdate of user profile")
  void test_birthdate_value_holder_assign_plain_value() {
    Object holder = new Object();
    BirthdateValueHolder<Object> value = new BirthdateValueHolder<>(holder);
    Assertions.assertSame(holder, value.birthdate("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getBirthdateValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getBirthdate().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.birthdateNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getBirthdateValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getBirthdate().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of birthdate of user profile")
  void test_birthdate_value_holder_assign_value_object() {
    Object holder = new Object();
    BirthdateValueHolder<Object> value = new BirthdateValueHolder<>(holder);
    BirthdateVO vo = BirthdateVO.from("one");
    Assertions.assertFalse(value.getBirthdateValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.birthdate(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getBirthdateValue().orElseThrow());
    Assertions.assertSame(holder, value.birthdate(Optional.empty()));
    Assertions.assertFalse(value.getBirthdateValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.birthdate(Optional.of(vo)));
    Assertions.assertSame(vo, value.getBirthdateValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of birthdate of user profile against the original")
  void test_birthdate_value_holder_read() {
    Object holder = new Object();
    BirthdateValueHolder<Object> value = new BirthdateValueHolder<>(holder);
    BirthdateVO vo = BirthdateVO.from("one");
    BirthdateVO other = BirthdateVO.from("one");
    UserProfile original = Mockito.mock(UserProfile.class);
    Mockito.when(original.getBirthdateValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readBirthdate(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readBirthdate(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.birthdate(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readBirthdate(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readBirthdate(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of birthdate of user profile")
  void test_birthdate_value_holder_unset() {
    Object holder = new Object();
    BirthdateValueHolder<Object> value = new BirthdateValueHolder<>(holder);
    BirthdateVO vo = BirthdateVO.from("one");
    value.birthdate(vo);
    Assertions.assertSame(holder, value.unsetBirthdateIfMatches("birthdate_other"));
    Assertions.assertTrue(value.getBirthdateValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetBirthdateIfMatches("birthdate"));
    Assertions.assertFalse(value.getBirthdateValue().isPresent(),
        "The field name must clear the value");
    value.birthdate(vo);
    Assertions.assertSame(holder, value.unsetBirthdate());
    Assertions.assertFalse(value.getBirthdateValue().isPresent(), "Unset must clear the value");
  }
}
